import { useRef, useState } from "react";
import clsx from "clsx";
import { Icon } from "../ui/icons.jsx";
import { Button, Chevron, Popover, useDisclosure, useStableId } from "../ui/primitives.jsx";
import { usePage } from "../contexts.jsx";
import { useApi } from "../../lib/data.js";
import { formatTime, formatWeekday } from "../../lib/format.js";
import { interactionTracking } from "../../lib/tracking.js";
import { Box, Item, Paragraph, Text } from "../ui/ds.jsx";

const temperatureFormat = new Intl.NumberFormat("de-DE", { style: "unit", unit: "celsius", maximumFractionDigits: 0 });
const percentFormat = new Intl.NumberFormat("de-DE", { style: "percent" });

function conditionIcon(condition) {
    if (/Regen|Schauer|Gewitter|Schnee/.test(condition))
        return "rain";
    if (/wolkig|bedeckt|Nebel/.test(condition))
        return "cloud";
    return "sun";
}

function Hourly({ hours }) {
    return (
        <ol className="flex gap-2 overflow-x-auto pb-1 scrollbar-none">
            {hours.map((hour) => (
                <Item key={hour.time} className="flex w-14 shrink-0 flex-col items-center gap-1 rounded-sm bg-paper-muted py-2 text-xs">
                    <Text className="text-ink-500">{formatTime(hour.time).replace(" Uhr", "")}</Text>
                    <Icon name={conditionIcon(hour.condition)} size={18} className="text-signal-500" />
                    <Text className="font-bold">{temperatureFormat.format(hour.temperature)}</Text>
                    <Text className="text-[0.625rem] text-video-500">{percentFormat.format(hour.precipitation / 100)}</Text>
                </Item>
            ))}
        </ol>
    );
}

function Daily({ days }) {
    return (
        <ul className="mt-3 divide-y divide-ink-100">
            {days.map((day) => (
                <Item key={day.date} className="flex items-center gap-3 py-1.5 text-sm">
                    <Text className="w-8 text-ink-500">{formatWeekday(day.date)}</Text>
                    <Icon name={conditionIcon(day.condition)} size={16} className="text-signal-500" />
                    <Text className="flex-1 text-ink-700">{day.condition}</Text>
                    <Text className="text-ink-500 tabular-nums">{temperatureFormat.format(day.min)}</Text>
                    <Text className="h-1.5 w-16 rounded-full bg-linear-to-r from-video-500 to-signal-500" />
                    <Text className="font-bold tabular-nums">{temperatureFormat.format(day.max)}</Text>
                </Item>
            ))}
        </ul>
    );
}

function Forecast({ cityId }) {
    const { data, loading } = useApi(`weather/${cityId}.json`);
    if (loading || !data)
        return <Box className="h-64 animate-pulse rounded-sm bg-ink-100" />;
    return (
        <Box data-testid="weather-forecast">
            <Box className="mb-3 flex items-center gap-3">
                <Icon name={conditionIcon(data.current.condition)} size={36} className="text-signal-500" />
                <Box>
                    <Paragraph className="text-head-l font-bold">{temperatureFormat.format(data.current.temperature)}</Paragraph>
                    <Paragraph className="text-xs text-ink-500">{data.current.condition}, gefühlt {temperatureFormat.format(data.current.feelsLike)}, Wind {data.current.wind} km/h</Paragraph>
                </Box>
            </Box>
            <Hourly hours={data.hourly} />
            <Daily days={data.daily} />
        </Box>
    );
}

export default function WeatherWidget() {
    const page = usePage();
    const anchorRef = useRef(null);
    const { open, toggle, close } = useDisclosure();
    const [cityId, setCityId] = useState(page.weather.defaultCity);
    const [picking, setPicking] = useState(false);
    const id = useStableId("weather");
    const city = page.weather.cities.find((c) => c.id === cityId);
    const { data } = useApi(`weather/${cityId}.json`);
    return (
        <>
            <Button ref={anchorRef} aria-expanded={open} aria-label={`Wetter für ${city.name}`} onClick={toggle} className="text-xs" {...interactionTracking("weather")}>
                <Icon name={data ? conditionIcon(data.current.condition) : "sun"} size={16} className="text-signal-500" />
                <Text className="font-medium">{city.name}</Text>
                {data ? <Text className="font-bold">{temperatureFormat.format(data.current.temperature)}</Text> : null}
                <Chevron open={open} />
            </Button>
            <Popover anchorRef={anchorRef} open={open} onClose={close} labelledBy={id} align="end" className="w-[26rem]">
                <Box className="mb-3 flex items-center justify-between">
                    <h3 id={id} className="text-sm font-bold">Wetter in {city.name}</h3>
                    <Button variant="chip" aria-expanded={picking} aria-label="Ort ändern" onClick={() => setPicking(!picking)}>Ort ändern</Button>
                </Box>
                {picking ? (
                    <ul className="mb-3 grid grid-cols-3 gap-1" aria-label="Orte">
                        {page.weather.cities.map((c) => (
                            <Item key={c.id}>
                                <button type="button" aria-label={`Wetter für ${c.name} anzeigen`} className={clsx("w-full truncate rounded-sm px-2 py-1 text-left text-sm hover:bg-brand-50", c.id === cityId && "font-bold text-brand-700")} onClick={() => {
                                    setCityId(c.id);
                                    setPicking(false);
                                }}>{c.name}</button>
                            </Item>
                        ))}
                    </ul>
                ) : null}
                <Forecast cityId={cityId} />
            </Popover>
        </>
    );
}
